<?php require_once __DIR__.'/../../includes/functions.php';$u=require_auth();$d=request_json();verify_csrf($d['_csrf']??'');$id=(int)($d['id']??0);if($id===root_folder_id($u['id']))json_response(['error'=>'Cannot delete the root folder.'],409);$st=db()->prepare('SELECT id FROM folders WHERE id=? AND user_id=?');$st->execute([$id,$u['id']]);if(!$st->fetch())json_response(['error'=>'Folder not found.'],404);$st=db()->prepare('SELECT COUNT(*) FROM files WHERE folder_id=? AND user_id=? AND is_deleted=0');$st->execute([$id,$u['id']]);if((int)$st->fetchColumn()>0)json_response(['error'=>'Folder is not empty.'],409);db()->prepare('DELETE FROM folders WHERE id=? AND user_id=?')->execute([$id,$u['id']]);json_response(['ok'=>1]);